// contractAssertNextZeroOnError asserts Next returns the zero Value and bool alongside any error.
func contractAssertNextZeroOnError(
	tb testing.TB,
	c Contract,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, got2, err := c.Next(ctx)
	if err == nil {
		tb.Skip("Next answered for a cancelled context, so this check has no error to inspect")
	}

	var zero cursor.Value
	if got != zero {
		tb.Errorf("Next must return the zero Value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
	var zero2 bool
	if got2 != zero2 {
		tb.Errorf("Next must return the zero bool alongside an error: got %+v, want %+v (err %v)",
			got2, zero2, err)
	}
}

